    /**
     * Handles create a Claim.  if not key provided, calls create, otherwise calls save
     * @param		Claim	claim
     * @return		Claim 
     */
	@PostMapping("/create")
    public Claim create( @RequestBody(required=true) CreateClaimCommand command ) {
    	Claim entity = null;

		entity = service.createClaim( command );
		LOGGER.info( "Successfully created Claim with Id " + entity.getClaimId()  );

		return entity;
    }

    /**
     * Handles updating a Claim.  if no key provided, calls create, otherwise calls save
     * @param		Claim claim
     * @return		Claim
     */
	@PutMapping("/update")
    public Claim update( @RequestBody(required=true) UpdateClaimCommand command ) {
		Claim entity = null;

		entity = service.updateClaim(command);
		LOGGER.info( "Successfully updated Claim with Id " + command.getClaimId()  );

		return entity;
	}
 
    /**
     * Handles deleting a Claim entity
     * @param		command ${class.getDeleteCommandAlias()}
     */
    @DeleteMapping("/delete")    
    public void delete( @RequestBody(required=true) DeleteClaimCommand command ) {                
		service.delete( command );
		LOGGER.info( "Successfully deleted Claim with Id " + command.getClaimId()  );
	}
	
    /**
     * Handles loading a Claim using a UUID
     * @param		UUID uuid 
     * @return		Claim
     */    
    @GetMapping("/load")
    public Claim load( @RequestParam(required=true) UUID uuid ) {
    	Claim entity = service.getClaim( new ClaimFetchOneSummary( uuid ) );

		LOGGER.info( "Successfully loaded Claim with Id " + uuid   );

        return entity;
    }

    /**
     * Handles loading all Claim business objects
     * @return		Set<Claim>
     */
    @GetMapping("/")
    public List<Claim> loadAll() {                
    	List<Claim> claimList = null;

		claimList = service.getAllClaim();
		LOGGER.info( "successfully loaded all Claims" );

        return claimList;
                            
    }

